  ["f74635b18b8bbe93"] = { "はい、どうぞ、{name}。この幽霊の姿でも占いと召喚の力がまだ使えるのは助かるだろ？", "." },
  ["f746bf314924ff11"] = { "いい鋼だ、{name}。金槌を取ってこっちへ来い、伝説の武器を鍛える秘訣を見せてやろう。", "." },
